SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0160000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "16", "printedPageNumber": 16, "pdfPageNumber": 399, "sequenceIndex": 6, "verificationStatus": "in_review", "scanLanguages": ["en"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": false, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000005", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—IV(b)", "sourceIdentifier": "IV(b)", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0160000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000005", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"The likeness of five times daily salaat is as the likeness of a deep brook running in front of the door of a person who bathes therein five times a day.\" Running water is generally free from dirt, and the deeper it runs the cleaner and purer it is. A bath in such water surely removes dirt from the body and makes it clean. Salaat offered with due regard for its essentials likewise cleanses the soul of all sins. There are several ahaadith of the same meaning, though. with slight variations in expression, narrated by different companions of the Prophet (Sallallaho alaihe wasallam). Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: ''Each of the five salaats expiates the sins committed since the salaat preceding it. To explain. let us take the case of a person working in a factory. His job is such that his body gets covered with dust. But there are five streams of running water in between the factory and his house and, on his return from the job, he takes a bath in each stream. The effect of five times daily salaat is quite similar. Any sins of omission and commission between two salaats are.forgiven on account of ''istighfaar and taubah in each salaat.'' The Prophet (Sallallaho alaihe wasallam) through such parables, aims at impressing that salaat has the wonderful power of removing the sins. If we fail to avail of Allah''s mercy, surely we ourselves are the losers. To err is human. We are -likely to commit innumerable acts of displeasing Allah and deserve thereby. His wrath and punishment, but look how relenting our dear Allah is! He has most graciously shown us the way to earn His mercy and forgiveness. It is a great pity if we do not avail of this great favour. Our Allah is always eager to show us His mercy on very small younds. It is said in a hadith, that if a person goes to bed with the intention of getting up for Tahajjud and perchance does not wake up, he receives the full reward for Tahajjud, although he has been enjoying his sleep at the time of Tahajjud. How boundless is the grace of Allah and what a tremendous loss and deprivation if we do not receive blessings from such a Giver.", "rawOcrText": "16 Virtues of Salaat \"The likeness of five times daily salaat is as the like- ness of a deep brook running in front of the door of a person who bathes therein five times a day.\" Running water is generally free from dirt, and the deeper it runs the cleaner and purer it is. A bath in such water surely removes dirt from the body and makes it clean. Salaat offered with due regard for its essentials like- wise cleanses the soul of all sins. There are several ahaa- dith of the same meaning, though. with slight variations in expression, narrated by different companions of the Prophet (Sallallaho alaihe wasallam). Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alame wasallam) saying: ''Each of the five salaats expiates the sins committed since the salaat preceding it. To explain. let us take the case of a person working in a factory. His job is such that his body gets covered with dust. But there are five streams of running water in between the factory and his house and, on his return from the job, he takes a bath in each stream. The effect of five times daily salaat is quite similar. Any sins of omission and com- mission between two salaats are .forgiven on account of ''istighfaar and taubah in each salaat.'' The Prophet (Sallallaho alaihe wasallam) through such parables, aims at impressing that salaat has the wonderful power of removing the sins. If we fail to avail of Allah''s mercy, surely we ourselves are the losers. To err is human. We are -likely to commit innumerable acts of displeasing Allah and deserve thereby. His wrath and punishment, but look how relenting our dear Allah is! He has most graciously shown us the way to earn His mercy and forgiveness. It is a great pity if we do not avail of this great favour. Our Allah is always eager to show us His mercy on very small younds. It is said in a hadith, that if a person goes to bed with the intention of getting up for Ta- hajjud and perchance does not wake up, he receives the full reward for Tahajjud, although he has been enjoying his sleep at the time of Tahajjud. How boundless is the grace of Allah and what a tremendous loss and deprivation if we do not receive blessings from such a Giver.", "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 16}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0170000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "17", "printedPageNumber": 17, "pdfPageNumber": 400, "sequenceIndex": 7, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000006", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0170000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 0, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—V", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0170000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ رَسُولُ اللَّهِ ﷺ إِذَا حَزَبَهُ أَمْرٌ فَزِعَ إِلَى الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0170000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أخرجه أحمد وأبو داود وابن جرير كذا في الدر المنثور", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0170000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"Hadhrat Huzaifah (Radhiyallaho anho) says that, whenever the Prophet (Sallallaho alaihe wasallam) happened to face any difficulty, he would at once resort to.salaat. \" Salaat is a great blessing of Allah. To resort to salaat at the time of worry is to hasten towards His mercy, and when Allah''s mercy comes to rescue, there can remain no trace of any worry. There are many traditions concerning this practice of the Holy Prophet (Sallallaho alaihe wasallam). Similar was the practice of his companions, who followed him in the minutest detail: Abu Darda (Radhiyallaho anho) says: -\"Whenever a strong wind blew, the Prophet (Sallallaho alaihe wasallam) would immediately enter the musjid and would not leave until the wind had subsided. Similarly, at the time of a solar or lunar eclipse, the Prophet (Sallallaho alaihe wasallam) would at once start offering salaat. Hadhrat Suhaib (Radhiyallaho anho) was informed by the Prophet (Sallallaho alaihe wasallam) that all the previous Apostles of Allah (peace be upon them) also used to resort to salaat in all adversities. Hadhrat Ibno Abbas (Radhiyallaho anho) was once on journey. On his way he got the news of the death of his son. He got down from his camel and offered two rakaats of salaat, praying in Tashahhud for a long time. He then recited ''Innaa lillaahi wa innaallaihi raaji-oon'' and said, \"I have done what Allah has ordered us to do in His Holy Book i.e.: \" Seek Allah''s help with patience and salaat\" (II: 45). Another similar story is narrated about him. He was on a journey when he received the news about the death of his brother Quthum. He descended from his camel by the roadside, and performed two rakaats of salaat and kept praying in Tashahhud for a long time. After finishing his salaat, he", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 17}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0180000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "18", "printedPageNumber": 18, "pdfPageNumber": 401, "sequenceIndex": 8, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000006", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0180000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "rode his camel reciting the following verse of the Holy Qur''an:", "rawOcrText": "18 Virtues of Salaat rode his camel reciting the following verse of the Holy Qur''an: \"Seek Allah''s help with patience and salaat, and truly it is indeed hard except to the humble minded.\" (11:45). There is yet another story about him. On hearing of the death of a wife of the Holy Prophet (Sallallaho alaihe wa- sallam), he fell down prostrate. When somebody asked him the reason he said, \"Our dear Prophet (SaHal-laho alaihe wasallam) had enjoined on us to prostrate (in salaat) when- ever a calamity were to béfall What calamity can be g•eater than the death of the Ummul-üo''mineen?\" When Hadhrat Ubaada (Radhiyallaho anho) was about to breathe his last, he said to the people around him, \"1_ prohibit one and all from crying over me. When my \"ul departs, I ask every one to perform wudhu, observing all its essentials, and to go to the musjid and pray for my forgive- ness, because our Gracious Allah has enjoined on us to \"Seek help with patience and salaat.\" After that, lay me down in the pit of my grave.\" Hadhrat Nadhr (Radhiyallaho anho) narrates, \"Once it became very dark during the day in Madina. I hurriedly went to Hadhrat Anas (Radhiyallaho anho) to know if he had ever experienced similar conditions during the life- time of the Holy Prophet (Sallallaho alaibe wasallam). He said to me, During those blessed days, whenever the. wind blew strong, we would hurry to the musjid lest it should be the approach of the Last Day. \" Hadhrat Abdullah bin Salaam (Radhiyallaho anho) narrates that whenever the members of the Prophet''s family were hardpressed in any . way, the Prophet (Sallallaho alaihe wasallam) would enjoin upon them to say salaat, and would recite the following verse of the Holy Qur''an:", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "“Seek Allah''s help with patience and salaat, and truly it is indeed hard except to the humble minded.” (II: 45).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000006", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "There is yet another story about him. On hearing of the death of a wife of the Holy Prophet (Sallallaho alaihe wasallam), he fell down prostrate. When somebody asked him the reason he said, “Our dear Prophet (Sallallaho alaihe wasallam) had enjoined on us to prostrate (in salaat) whenever a calamity were to befall us. What calamity can be greater than the death of the Ummul-Mo’mineen?” When Hadhrat Ubaada (Radhiyallaho anho) was about to breathe his last, he said to the people around him, “I prohibit one and all from crying over me. When my soul departs, I ask every one to perform wudhu, observing all its essentials, and to go to the musjid and pray for my forgiveness, because our Gracious Allah has enjoined on us to “Seek help with patience and salaat.” After that, lay me down in the pit of my grave.” Hadhrat Nadhr (Radhiyallaho anho) narrates, “Once it became very dark during the day in Madina. I hurriedly went to Hadhrat Anas (Radhiyallaho anho) to know if he had ever experienced similar conditions during the lifetime of the Holy Prophet (Sallallaho alaihe wasallam). He said to me, “Ma’athallaah! During those blessed days, whenever the wind blew strong, we would hurry to the musjid lest it should be the approach of the Last Day.”", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Salaam (Radhiyallaho anho) narrates that whenever the members of the Prophet''s family were hardpressed in any way, the Prophet (Sallallaho alaihe wasallam) would enjoin upon them to say salaat, and would recite the following verse of the Holy Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0180000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَى", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 18}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0190000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "19", "printedPageNumber": 19, "pdfPageNumber": 402, "sequenceIndex": 9, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000006", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0190000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 0, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And enjoin salaat upon thy people and be thyself constant therein. We ask not of thee to provide sustenance. We provide it for thee. And the Hereafter is for the righteousness.” (XX: 132).\"", "rawOcrText": "Part I (a)—lmportance of Salaat 19 \"And enjoin salaat upon thy people and be thyself constant therein. We ask not of to provide suste- nance. We provide it for thee. And the Hereafter •is for (xx:.132). the righteousness.\" It is said in a hadith that when somebody is confronted with a need, whether pertaining to this life or the Hereafter, or whether it concerns Allah or a mortal, he should per- form a perfect wudhu, offer salaat of two rakaats, glorify Allah, then ask blessing for the Prophet (Sallallaho alaihe wasallam), and then pray as under: \"There is no god save Allah—the Clemént—the Bounti- ful. Glorified be Allah, the Lord of the tremendous throne. Praise be to Allah, the Lord of the worlds. I ask Thee all that leadeth to Thy Mercy and deserveth Thy forgiveness. I ask Thee abundance in all that is good and refuge from all that is evil. Leave me no sin but Thou pardOnest it, and no distress but Thou removest it, and no need but Thou fulfillest it. O, most Merciful of those who show mercy!\" Wahb bin Munabbih writes: \"Have your needs fulfilled by Allah through salaat. In the good old time, if a calamity befell the people, they would hurry towards salaat.\" It said that in Koofah there was a porter who was well known for his honesty. People trusted him with their valuables and money, which he carried from one place to another. Once he was on his usual errand when a person met him on the way and asked him about his destination. When the porter gave him the required information, he said, \"I am also bound for the same destination. If I could walk, I would have accompanied you on foot. Will you kindly give me a lift on your mule for one dinaar?\" The porter agreed and allowed him to share the mule with him. They came to a crossing on the way. The person said, ''Now, which road will you take?'' ''The main road, of course,'' replied the porter. The person said, ''No, brother. We should go by the", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0190000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said in a hadith that when somebody is confronted with a need, whether pertaining to this life or the Hereafter, or whether it concerns Allah or a mortal, he should perform a perfect wudhu, offer salaat of two rakaats, glorify Allah, then ask blessing for the Prophet (Sallallaho alaihe wasallam), and then pray as under:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0190000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "لَا إِلٰهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ سُبْحَانَ اللَّهِ رَبِّ الْعَرْشِ الْعَظِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ وَعَزَائِمَ مَغْفِرَتِكَ وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ وَلَا هَمًّا إِلَّا فَرَّجْتَهُ وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا يَا أَرْحَمَ الرَّاحِمِينَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0190000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"There is no god save Allah—the Clement—the Bountiful. Glorified be Allah, the Lord of the tremendous throne. Praise be to Allah, the Lord of the worlds. I ask Thee all that leadeth to Thy Mercy and deserveth Thy forgiveness. I ask Thee abundance in all that is good and refuge from all that is evil. Leave me no sin but Thou pardonest it, and no distress but Thou removest it, and no need but Thou fulfillest it. O, most Merciful of those who show mercy!\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0190000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Wahb bin Munabbih writes: \"Have your needs fulfilled by Allah through salaat. In the good old time, if a calamity befell the people, they would hurry towards salaat.\" It is said that in Koofah there was a porter who was well known for his honesty. People trusted him with their valuables and money, which he carried from one place to another. Once he was on his usual errand when a person met him on the way and asked him about his destination. When the porter gave him the required information, he said, \"I am also bound for the same destination. If I could walk, I would have accompanied you on foot. Will you kindly give me a lift on your mule for one dinaar?\" The porter agreed and allowed him to share the mule with him. They came to a crossing on the way. The person said, ''Now, which road will you take?'' ''The main road, of course,'' replied the porter. The person said, ''No, brother. We should go by the", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 19}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0200000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "20", "printedPageNumber": 20, "pdfPageNumber": 403, "sequenceIndex": 10, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000006", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0200000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "other road which is a shortcut and there is plenty of grass. enroute to feed the animal.'' The porter said, ''I have never been on this path.'' The person remarked, ''But I have travelled by this route quite often''. The porter believed him and put the animal on that path. After some distance, the path ended in a terrifying forest where a large number of dead bodies were lying about. All of a sudden the person jumped down from the mule and took out his knife with the intention of slaying the porter. ''Hold your hand'', shouted the porter, ''Take the animal and its load, but do not kill me''. The person refused to listen to his entreaty and swore that he would first kill the porter and then take possession of the animal and the goods. Seeing that his entreaties fell on deaf ears and that his cruel heart would not melt, the porter said to him, ''All right if you must kill me, then permit to say my salaat of only two rakaats.'' The person agreed and remarked, ''You can please yourself. All the dead you see over here made the same request, but their salaat was of no avail to them.''. The porter started the salaat, but could not recollect any soorah to connect with the Fatihah, in spite-of his best efforts. Meanwhile the person grew impatient and pressed him hard to hurry up with the salaat. All of a sudden the following verse flashed to his mind:", "rawOcrText": "20 Virtues of Salaat other road which is a shortcut and there is plenty of grass. enroute to feed the animal.'' The porter said, ''I hive never been on this path.'' The person remarked, ''But I have travel- led by this route quite often''. The porter believed him and put the animal on that path. After some distance, the path ended in a terrifying forest where a large number of dead bodies were lying about. All of a sudden the person jumped down from the mule and took out his knife with the intention of slaying the porter. ''Hold your hand'', shouted the porter, ''Take the animal and its load, but do not kill me''. The person refused to listen to his entreaty and swore that he would first kill the porter and then take possession of the animal and the goods. Seeing that his en- treaties fell on deaf ears and that his cruel heart would not melt, the porter said to him, ''All right if you must kill me, then permit to say my salaat of only two rakaats.'' The person ageed and remarked, ''You can please yourself. All the dead you see over here made the same request, but their salaat was of no avail to them.''. The porter started the salaat, but could not recollect any soorah to connect with the Fatihah, in spite-of his best efforts. Meanwhile the person grew impatient and pressed him hard to hurry up with the salaat. All of a sudden the following verse flashed to his mind: ''Is it not He Who answereth the vwonged one when he crieth unto Him, and removeth the evil. •.. (XXVII-62). The porter was reciting the verse and the tears welled up in his eyes, when a horseman suddenly appeared on the scene. He was wearing a glittering helmet and held a spear in his hand. He pierced the body of the pitiless rogue with his spear and killed him there and then. A flame of fire rose from the spot where•the dead body fell. The porter fell down prostrate and thanked Allah. After finishing his salaat, he ran towards the horseman and requested him to disclose his identity. He replied, ''I am a slave to Him •who answereth the wronged one. You are now safe and can go wherever you like.'' Saying this, the horseman rode away and disappeared.\" Indeed salaat is a tremendous asset. Besides pleasing Allah it often gets us deliverence from the calamities of this", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0200000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0200000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "''Is it not He Who answereth the wronged one when he crieth unto Him, and removeth the evil . . .” (XXVII-62).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0200000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000006", "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The porter was reciting the verse and the tears welled up in his eyes, when a horseman suddenly appeared on the scene. He was wearing a glittering helmet and held a spear in his hand. He pierced the body of the pitiless rogue with his spear and killed him there and then. A flame of fire rose from the spot where the dead body fell. The porter fell down prostrate and thanked Allah. After finishing his salaat, he ran towards the horseman and requested him to disclose his identity. He replied, ''I am a slave to Him who answereth the wronged one. You are now safe and can go wherever you like.'' Saying this, the horseman rode away and disappeared.\" Indeed salaat is a tremendous asset. Besides pleasing Allah it often gets us deliverence from the calamities of this", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 20}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0210000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "21", "printedPageNumber": 21, "pdfPageNumber": 404, "sequenceIndex": 11, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000007", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0210000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000007", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "life and provides us with tranquility and peace of mind. Ibn Seereen writes: \"If I be allowed to choose between Paradise and salaat of two rakaats, I would prefer salaat. The reason is quite clear. Paradise is for my own pleasure while salaat is for the pleasure of my dear Lord.\" The Holy Prophet (Sallallaho alaihe wasallam) has said: \"Enviable is the lot of that Muslim who is with least encumbrance, whose main fortune is salaat, who remains content with humble provision throughout his life, who worships his Lord in a dutiful manner, who lives a nameless life and who dies an early death, with very little to bequeath and very few to mourn him.\" In another hadith, the Holy Prophet (Sallallaho alaihe wasallam) is reported to have said: ''Offer your salaat at your homes quite frequently, so that these may be blessed with Allah''s Grace and Mercy. \"", "rawOcrText": "Part I (a)—lmportance of Salaat 21 life and provides us with tranquility and peace of mind. Ibn Seereen writes: \"If I be allowed to choose between Paradise and salaat of two rakaats, I would prefer salaat. The reason is quite clear. Paradise is for my own pleasure while salaat is for the pleasure of my dear Lord.\" The Holy Prophet (Sallallaho alaihe wasallam) has said: \"Enviable is the lot of that Muslim who is with least encumbrance, whose main fortune is salaat, who remains content with humble provision throughout his life, who worships his Lord in a dutiful manner, who lives a nameless life and who dies an early death, with very little to bequeath and very few to mourn him.\" In anothef hadith, the Holy Prophet (Sallallaho alaihe wasallam) is reported to have said: ''Offer your salaat at your homes quite frequently, so that these may be blessed with Allah''s Grace and Mercy. \" Hadith.—VI \"Abu Muslim narrates: I went to see Abu Umaamah (Radhiyallaho anho) while he was in the musjid. I asked him if he had really heard the Holy Prophet (Sal- lallaho alaihe wasallam) saying, \"When a person per- forms wudhu with right performance and then says his fardh salaat, Allah forgives him all the sins committed that day by his feet in going towards evil, by his hands in doing evil, by his ears in listening to evil, by his eyes in looking at evil and by his heart in thinking of evil.'' He replied, ''By Allah, I have heard these words from the Holy Prophet (Sallallaho alaihe wasallam) again and again. \" Many of the companions have narrated this Hadith with slight variations. Those endowed with the power of Kashf can even witness the sins being shed. It is said of", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0210000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000007", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—VI", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0210000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000007", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أَبِي مُسْلِمٍ الْخَوْلَانِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ دَخَلْتُ عَلَى أَبِي أُمَامَةَ وَهُوَ فِي الْمَسْجِدِ فَقُلْتُ يَا أَبَا أُمَامَةَ إِنَّ رَجُلًا حَدَّثَنِي عَنْكَ أَنَّكَ سَمِعْتَ رَسُولَ اللَّهِ ﷺ يَقُولُ مَنْ تَوَضَّأَ فَأَسْبَغَ الْوُضُوءَ فَغَسَلَ يَدَيْهِ وَوَجْهَهُ وَمَسَحَ عَلَى رَأْسِهِ وَأُذُنَيْهِ ثُمَّ قَامَ إِلَى صَلَاةٍ مَفْرُوضَةٍ غَفَرَ اللَّهُ لَهُ فِي ذَلِكَ الْيَوْمِ مَا مَشَتْ إِلَيْهِ رِجْلَاهُ وَقَبَضَتْ عَلَيْهِ يَدَاهُ وَسَمِعَتْ إِلَيْهِ أُذُنَاهُ وَنَظَرَتْ إِلَيْهِ عَيْنَاهُ وَحَدَّثَتْ بِهِ نَفْسُهُ مِنْ سُوءٍ فَقَالَ وَاللَّهِ لَقَدْ سَمِعْتُهُ مِنَ النَّبِيِّ ﷺ مِرَارًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0210000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000007", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رواه أحمد والطبراني على سنده الحسن", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0210000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000007", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"Abu Muslim narrates: I went to see Abu Umaamah (Radhiyallaho anho) while he was in the musjid. I asked him if he had really heard the Holy Prophet (Sallallaho alaihe wasallam) saying, \"When a person performs wudhu with right performance and then says his fardh salaat, Allah forgives him all the sins committed that day by his feet in going towards evil, by his hands in doing evil, by his ears in listening to evil, by his eyes in looking at evil and by his heart in thinking of evil.'' He replied, ''By Allah, I have heard these words from the Holy Prophet (Sallallaho alaihe wasallam) again and again. \" Many of the companions have narrated this Hadith with slight variations. Those endowed with the power of Kashf can even witness the sins being shed. It is said of", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 21}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0220000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "22", "printedPageNumber": 22, "pdfPageNumber": 405, "sequenceIndex": 12, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000008", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0220000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Imam Abu Haneefa (Rahmatullah alaih) that he could tell from the water falling down from the limbs of the person performing wudhu as to which sins had been washed off therewith. In a narration by Hadhrat Uthman (Radhiyallaho anho), the Holy Prophet (Sallallaho alaihe wasallam) is reported to have warned against being wrong-headed in committing sins in the hope of getting them redeemed through salaat. We have, really, no ground to behave as such on this account. After all, what is the quality of the salaat that we offer? If Allah merely absolves us of our obligation it is His very special favour and grace. Again it is the height of ingratitude to disobey Allah just because He is Clement, Merciful and Forgiving.", "rawOcrText": "22 Virtues of Salaat Imam Abu Haneefa (Rahmatullah alaih) that he could tell from the water falling down from the limbs of the person peRorming wudhu as to which sins had been washed off therewith. In a narration by Hadhrat Uthman (Radhiyallaho anho), the Holy Prophet (Sallallaho alaihe wasallam) is re- ported to have warned against being wrong-headed in come mitting sins in the hope of getting them redeemed thröugh salaat. We have, really, no ground to behavm as such on this account. After all, what is the quality of the salaat that we offer? If Allah merely absolves us of our obligation it is His very special favour and gace. Again it is .the height of ing•atitude to disobey Allah just because He is Clement, Merciful and Forgiving. Hadith—VII Hadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"Two persons of one clan came to Prophet (Sallallaho alaihe wasallam) embraced Islam at one and the same time. One of these was martyred in a battle and the other died a year later, Hadhrat Talha bin Ubaidul- lah (Radhiyallaho anho) says that he saw in his dream that the person who had died later was admitted into Paradise before .the martyr. This surprised him. I do not •recollect whether it was he .or somebody else who narrated this dream. The Prophet (Sallallaho alaihe wasallam) thereupon remarked: \"Has not the person dying later fasted for one additional month of Rama- dhaan, and has he not offered six thousand or odd ra- kaats of salaat more during the year he lived after the Really, we do not know how valuable salaat is! The Holy Prophet (Sallallaho alaihe wasallam) was often heard", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—VII", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ رَجُلَانِ مِنْ بَلِيٍّ حَيٍّ مِنْ قُضَاعَةَ أَسْلَمَا مَعَ رَسُولِ اللَّهِ ﷺ فَاسْتُشْهِدَ أَحَدُهُمَا وَأُخِّرَ الْآخَرُ سَنَةً قَالَ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ فَرَأَيْتُ الْمُؤَخَّرَ مِنْهُمَا أُدْخِلَ الْجَنَّةَ قَبْلَ الشَّهِيدِ فَتَعَجَّبْتُ لِذَلِكَ فَأَصْبَحْتُ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ﷺ أَوْ ذُكِرَ لِرَسُولِ اللَّهِ ﷺ فَقَالَ رَسُولُ اللَّهِ أَلَيْسَ قَدْ صَامَ بَعْدَهُ رَمَضَانَ وَصَلَّى سِتَّةَ آلَافِ رَكْعَةٍ وَكَذَا وَكَذَا رَكْعَةً صَلَاةَ سَنَةٍ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رواه أحمد بإسناد حسن ورواه ابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"Two persons of one clan came to Prophet (Sallallaho alaihe wasallam) embraced Islam at one and the same time. One of these was martyred in a battle and the other died a year later, Hadhrat Talha bin Ubaidullah (Radhiyallaho anho) says that he saw in his dream that the person who had died later was admitted into Paradise before the martyr. This surprised him. I do not recollect whether it was he or somebody else who narrated this dream. The Prophet (Sallallaho alaihe wasallam) thereupon remarked: \"Has not the person dying later fasted for one additional month of Ramadhaan, and has he not offered six thousand or odd rakaats of salaat more during the year he lived after the Really, we do not know how valuable salaat is! The Holy Prophet (Sallallaho alaihe wasallam) was often heard", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 22}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0230000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "23", "printedPageNumber": 23, "pdfPageNumber": 406, "sequenceIndex": 13, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000009", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—VIII", "sourceIdentifier": "VIII", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000010", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—IX", "sourceIdentifier": "IX", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0230000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "saying, \"The comfort of my eyes is in salaat.\" This is an expression of his profound love for salaat. As Such, what else can be more valuable than salaat?", "rawOcrText": "Part I (a)—lmportance of Salaat 23 saying, \"The comfort of my eyes is in salaat.\" This is an ex- pression of his profound love for salaat. As Such, what else can be more valuable than salaat? Hadith.—vm IJS Hadhrat Ibn Mas''ood (Radhiyallaho anho) nafrates that he heard the Holy Prophet (Sallallaho alaihe wasallam) saying: \"At the approach of the hour of a salaat, van An el is deputed to roclaim, ''Arise, O Children of Aa am! and extinguisk the fire that you have (by com- mitting sins) kindled to burn yourselves. So, the people rise up, perform wudhu and offer their Zuhr prayer. This causes forgiveness of their sins committed since day-break. The same is repeated at Asr, Maghrib and Ishaa. After Ishaa people go to bed, but there are some who busy themselves in good, while some others in evil deeds. Hadhrat Salmagn (Radhiyallaho anho) says, \"After Ishaa the people get divided into three goups. There are some for whom the night is a source of blessing and gain. They are those who spend .it in the worship of Allah, while other people are asleep. For them the night brings geat reward from their Lord.'' There are others who turn their night into a burden and curse for themselves, for they in- dulge in various dark deeds in the dead of night. To them the night brings woe and misery. There is the third group of people who go to bed immediately after Ishaa; they neither gain nor lose.\" Hadith.—1X Jij J;..j Jj Jj u; ''{i y JWj", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—VIII", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ ﷺ أَنَّهُ قَالَ يُبْعَثُ مُنَادٍ عِنْدَ حَضْرَةِ كُلِّ صَلَاةٍ فَيَقُولُ يَا بَنِي آدَمَ قُومُوا فَأَطْفِئُوا مَا أَوْقَدْتُمْ عَلَى أَنْفُسِكُمْ فَيَقُومُونَ فَيَتَطَهَّرُونَ وَيُصَلُّونَ الظُّهْرَ فَيُغْفَرُ لَهُمْ مَا بَيْنَهَا فَإِذَا حَضَرَتِ الْعَصْرُ فَمِثْلُ ذَلِكَ فَإِذَا حَضَرَ الْمَغْرِبُ فَمِثْلُ ذَلِكَ فَإِذَا حَضَرَتِ الْعَتَمَةُ فَمِثْلُ ذَلِكَ فَيَنَامُونَ فَمُدْلِجٌ فِي خَيْرٍ وَمُدْلِجٌ فِي شَرٍّ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رواه الطبراني في الكبير كذا في الترغيب", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ibn Mas''ood (Radhiyallaho anho) narrates that he heard the Holy Prophet (Sallallaho alaihe wasallam) saying: \"At the approach of the hour of a salaat, an Angel is deputed to proclaim, ''Arise, O Children of Aadam! and extinguish the fire that you have (by committing sins) kindled to burn yourselves. So, the people rise up, perform wudhu and offer their Zuhr prayer. This causes forgiveness of their sins committed since day-break. The same is repeated at Asr, Maghrib and Ishaa. After Ishaa people go to bed, but there are some who busy themselves in good, while some others in evil deeds. Hadhrat Salmaan (Radhiyallaho anho) says, \"After Ishaa the people get divided into three groups. There are some for whom the night is a source of blessing and gain. They are those who spend it in the worship of Allah, while other people are asleep. For them the night brings great reward from their Lord.'' There are others who turn their night into a burden and curse for themselves, for they indulge in various dark deeds in the dead of night. To them the night brings woe and misery. There is the third group of people who go to bed immediately after Ishaa; they neither gain nor lose.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000006", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—IX", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000007", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أَبِي قَتَادَةَ بْنِ رِبْعِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ ﷺ قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى إِنِّي افْتَرَضْتُ عَلَى أُمَّتِكَ خَمْسَ صَلَوَاتٍ وَعَهِدْتُ عِنْدِي عَهْدًا أَنَّهُ مَنْ جَاءَنِي يُحَافِظُ عَلَيْهِنَّ لِوَقْتِهِنَّ أَدْخَلْتُهُ الْجَنَّةَ وَمَنْ لَمْ يُحَافِظْ عَلَيْهِنَّ فَلَا عَهْدَ لَهُ عِنْدِي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000008", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Jij J;..j Jj Jj u; ''{i y JWj", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 23}'::jsonb);
SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000002'::uuid, '{"pageId": "c0240000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "24", "printedPageNumber": 24, "pdfPageNumber": 407, "sequenceIndex": 14, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000010", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—IX", "sourceIdentifier": "IX", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000011", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—X", "sourceIdentifier": "X", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0240000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 0, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "كذا في الدر المنثور برواية أبي داود وابن ماجه وفيه أيضا أخرج مالك وابن أبي شيبة وأحمد وأبو داود والنسائي وابن ماجه وابن حبان والبيهقي عن عبادة بن الصامت ذكر معنى حديث الباب مرفوعا بأطول منه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0240000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu. Qataadah bin Rab''iyy (Radhiyallaho anho) says, \"He heard the Prophet (Sallallaho alaihe wasallam) saying, Allah has said, \"O, Muhammad! I have ordained five times daily salaat for thy followers. I have made a covenant with myself that whosoever is regular in performing his salaat at its fixed hour, he shall be admitted into the Paradise. Those of thy followers who do not guard their salaat, are not included in this covenant. \" In another hadith, it is said that Allah has ordained five times salaat and whosoever is mindful of his salaat, by doing wudhu properly and by praying at fixed hours with sincerity and devotion, is assured by Allah of his entry into Paradise; and whosoever does not guard his salaat, there is no such guarantee for him; he. may—or may not be forgiven. salaat has indeed a tremendous value. It affords us an opportunity to receive Allah''s guarantee for Paradise. When an honourable person of some financial standing or having executive power gives us a guarantee or stands surety for meeting any of our requirements of this world, we feel quite satisfied and happy and we consider it our duty to remain obliged and devoted to him. Here Allah,the Absolute Sovereign of both the worlds, is giving the guarantee and is standing surety for the real success after death in return for five times daily salaat, which does not involve much effort on our part. If even then we do not avail of the opportunity, we shall have none to blame, but ourselves for the dreadful doom that awaits us.", "rawOcrText": "24 Virtues-of Salaat 4.*I.a 4.''rb Hadhrat Abu. Qataadah bin Rab''iyy (Radhiyallaho anho) says, \"He heard the Prophet (Sallallaho alaihe wasallam) saying, Allah has said, \"O, Muhammad! I have ordained five times daily salaat for thy followers. I have made a covenant with myself that whosoever is regular in performing his salaat at its fixed hour, he shall be admitted into the Paradisev Those of thy föl• lowers who do not guard their salaat, are not included in this covenant. \" .1n another hadith, it is said that Allah has ordained five times salaat and whosoever is mindful of his salaat, by doing wudhu properly and by praying at fixed hours with sincerity and devotion, is assured by Allah of his entry into Paradise; and whosoever does not guard his salaat, there is no such guarantee for him; he. may—or may not be forgiven. salaat has indeed a tremendous value. Jt affords us an op- portunity to receive Allah''s guarantee for Paradise. When an honourable person of some financial standing or having executive power gives us a guarantee or stands surety for meeting any of our requirements of this world, we feel quite satisfied and happy and we consider it our duty to remain obliged and devoted to him. Here Allah,the Abso- lute Sovereign of both the worlds, is giving the guarantee and is standing surety for the real success after death in return for five times daily salaat, which does not involve much effort on our part. If even then we do not avail of the opportunity, we shall have none to blame, but ourselves for the dreadful doom that awaits us. Hadith—X", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0240000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000011", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—X", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0240000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000011", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ ابْنِ سَلْمَانَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ ﷺ حَدَّثَهُ قَالَ لَمَّا فَتَحْنَا خَيْبَرَ أَخْرَجُوا غَنَائِمَهُمْ مِنَ الْمَتَاعِ وَالسَّبْيِ فَجَعَلَ النَّاسُ يَتَبَايَعُونَ غَنَائِمَهُمْ فَجَاءَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ لَقَدْ رَبِحْتُ رِبْحًا مَا رَبِحَ الْيَوْمَ مِثْلَهُ أَحَدٌ مِنْ أَهْلِ هَذَا الْوَادِي فَقَالَ وَيْحَكَ وَمَا رَبِحْتَ قَالَ مَا زِلْتُ أَبِيعُ وَأَبْتَاعُ حَتَّى رَبِحْتُ ثَلَاثَمِائَةِ أُوقِيَّةٍ فَقَالَ رَسُولُ اللَّهِ ﷺ أَنَا أُنَبِّئُكَ بِخَيْرِ رَجُلٍ رَبِحَ قَالَ مَا هُوَ يَا رَسُولَ اللَّهِ قَالَ رَكْعَتَيْنِ بَعْدَ الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 24}'::jsonb);
